import { ThreadNav, Card, threadPath } from "march/ui"

// tarif defteri bir ipte: öğünler boncuk, kategoriler kapsülde, tarifler alt iplikte; damla seçilen tarife akar
// bir yer: bölüm, kategori ya da sayfa (ThreadNav'ın öğe biçimi)
interface Item { id: string; label: string; desc?: string; count?: number; color?: string; href?: string; children?: Item[] }
const recipes: Item[] = [
  { id: "breakfast", label: "Kahvaltı", color: "brand-gold", children: [
    { id: "eggs", label: "Yumurtalar", count: 2, children: [
      { id: "menemen", label: "Menemen", desc: "Domates, biber, bol sabır" },
      { id: "cilbir", label: "Çılbır", desc: "Sarımsaklı yoğurt, kızgın tereyağı" },
    ] },
  ] },
  { id: "main", label: "Ana yemek", color: "brand-orange", children: [
    { id: "stews", label: "Tencere", count: 2, children: [
      { id: "kuru", label: "Kuru fasulye", desc: "Akşamdan ıslat, sabah unutma" },
      { id: "karniyarik", label: "Karnıyarık", desc: "Patlıcan, kıyma, fırın" },
    ] },
  ] },
  { id: "dessert", label: "Tatlı", color: "brand-pink", children: [
    { id: "milky", label: "Sütlü", count: 2, children: [
      { id: "sutlac", label: "Sütlaç", desc: "Fırında, üstü kızarmış" },
      { id: "kazandibi", label: "Kazandibi", desc: "Dibi tutması işin sırrı" },
    ] },
  ] },
]

export function RecipeThread() {
  let $dish = "menemen"
  const dish = () => threadPath(recipes, $dish).at(-1)
  // ThreadNav yerini doldurur: kapsülün yüksekliğini çevresindeki kutu verir (sx'te yükseklik yok, style nesnesi)
  return <div sx={{ flex: "row", gap: 3 }}>
    <div style={{ "block-size": "17rem" }}>
      <ThreadNav items={recipes} value={$dish} search={false} onNavigate={(it: Item) => $dish = it.id} />
    </div>
    <div sx={{ flex: "grow" }}>
      <Card title="Bugün ne pişirsek?">
        <p sx={{ text: "2xl", color: "brand-orange" }}>{dish()?.label}</p>
        <p sx={{ color: "muted" }}>{dish()?.desc}</p>
      </Card>
    </div>
  </div>
}

import { ThreadNav, Card, Badge, Button, threadPath, toast } from "march/ui"

// bir mağazanın yönetim paneli: bölümler iplikte, kategoriler kapsülde (sayılarıyla), sayfalar alt iplikte;
// kapalıyken kapsül konum yolunu gösterir, sağda seçilen sayfanın içeriği

// bir yer: bölüm, kategori ya da sayfa (ThreadNav'ın öğe biçimi)
interface Item { id: string; label: string; desc?: string; count?: number; color?: string; href?: string; children?: Item[] }
const sections: Item[] = [
  { id: "sales", label: "Satış", desc: "Siparişler ve iadeler", color: "brand-orange", children: [
    { id: "orders", label: "Siparişler", desc: "Bugün gelenler, kargodakiler", count: 3, children: [
      { id: "new", label: "Yeni", desc: "Onay bekleyen siparişler" },
      { id: "shipping", label: "Kargoda", desc: "Yolda olan paketler" },
      { id: "delivered", label: "Teslim edildi", desc: "Son 30 gün" },
    ] },
    { id: "returns", label: "İadeler", desc: "Bekleyen ve onaylanan", count: 2, children: [
      { id: "pending", label: "Bekleyen iadeler" },
      { id: "approved", label: "Onaylanan iadeler" },
    ] },
  ] },
  { id: "catalog", label: "Katalog", desc: "Ürünler ve stok", color: "brand-blue", children: [
    { id: "products", label: "Ürünler", count: 2, children: [{ id: "all", label: "Tüm ürünler" }, { id: "drafts", label: "Taslaklar" }] },
    { id: "stock", label: "Stok", count: 2, children: [{ id: "low", label: "Azalan stok" }, { id: "out", label: "Tükenenler" }] },
  ] },
  { id: "customers", label: "Müşteriler", desc: "Kategorisiz: boncuk sayfanın kendisi", color: "brand-green" },
]

// her sayfanın bekleyen iş sayısı (gerçekte bir query() olurdu)
const waiting: Record<string, number> = { new: 12, shipping: 31, pending: 4, low: 7, out: 2 }

export function ShopAdmin() {
  let $page = "new"
  const path = () => threadPath(sections, $page)
  const here = () => path().at(-1)
  return <div sx={{ flex: "row", gap: 3 }}>
    <div style={{ "block-size": "24rem" }}>
      <ThreadNav items={sections} value={$page} onNavigate={(it: Item) => $page = it.id}
        labels={{ group: "Yönetim", search: "Panelde ara", close: "Kapat", empty: "Böyle bir sayfa yok" }} />
    </div>
    <div sx={{ flex: "grow" }}>
      <Card title={here()?.label} subtitle={path().map((x: Item) => x.label).join(" › ")}>
        <div sx={{ flex: "col", gap: 2 }}>
          <span sx={{ color: "muted" }}>{here()?.desc ?? "Bu sayfada bekleyen bir açıklama yok."}</span>
          <div sx={{ flex: "row", gap: 2 }}>
            <Badge count={waiting[$page] ?? 0} />
            <span>{waiting[$page] ? "iş bekliyor" : "her şey yolunda"}</span>
          </div>
          <Button size="sm" variant="primary" disabled={!waiting[$page]} on:click={() => toast(`${here()?.label}: hepsi işlendi`)}>Hepsini işle</Button>
        </div>
      </Card>
    </div>
  </div>
}

import { ThreadNav, Toggle, threadPath } from "march/ui"

// ThreadNav'ın bütün özellikleri bir arada: items (id, label, desc, count, color, href, children; kategorisiz bir
// bölüm), value, onNavigate (öğe ve yol), fixed, magnify, reach, grow, bend, search, crumbs, closeOnNavigate,
// labels (group, search, close, empty) ve class; anahtarlar özellikleri canlı açıp kapatır

// bir yer: bölüm, kategori ya da sayfa (ThreadNav'ın öğe biçimi)
interface Item { id: string; label: string; desc?: string; count?: number; color?: string; href?: string; children?: Item[] }
const tree: Item[] = [
  { id: "start", label: "Başla", desc: "Kur ve öğren", color: "brand-orange", children: [
    { id: "setup", label: "Kurulum adımları", desc: "Depodan kur, ilk sayfa", count: 2, children: [
      { id: "install", label: "Depodan kur" }, { id: "cli", label: "march CLI", desc: "Geliştir, derle, denetle" },
    ] },
  ] },
  { id: "components", label: "Bileşenler", desc: "Arayüzün yapı taşları", color: "brand-blue", children: [
    { id: "forms", label: "Formlar", desc: "Alanlar ve seçiciler", count: 2, children: [{ id: "field", label: "Alan" }, { id: "select", label: "Seçim" }] },
    { id: "charts", label: "Grafikler", desc: "Çizgi, çubuk, pasta", count: 3, children: [
      { id: "line", label: "Çizgi" }, { id: "bar", label: "Çubuk", desc: "Gruplu ya da yatay" }, { id: "pie", label: "Pasta" },
    ] },
  ] },
  { id: "look", label: "Görünüm", desc: "Tema ve ikon", color: "brand-green", children: [
    { id: "themes", label: "Temalar", count: 1, children: [{ id: "presets", label: "Hazır temalar" }] },
  ] },
  { id: "about", label: "Hakkında", desc: "Sayfasız kategoriler: bağlantılar", color: "brand-purple", children: [
    { id: "notes", label: "Sürüm notları", href: "https://marchjs.com", desc: "Bağlantı: href verilen öğe bir a olur" },
  ] },
  { id: "profile", label: "Profil", desc: "Kategorisiz bölüm: boncuk kendisi gider", color: "brand-pink" },
]

export function ThreadNavLab() {
  let $page = "line"
  let $magnify = true
  let $bend = true
  let $search = true
  let $crumbs = true
  let $close = true
  let $last = ""
  return <div sx={{ flex: "row", gap: 4 }}>
    <div style={{ "block-size": "26rem" }}>
      <ThreadNav items={tree} value={$page} fixed={false} class="lab-thread"
        magnify={$magnify} reach={160} grow={30} bend={$bend} search={$search} crumbs={$crumbs} closeOnNavigate={$close}
        labels={{ group: "Lab gezinme", search: "Lab'da ara", close: "Kapsülü kapat", empty: "Burada bir şey yok" }}
        onNavigate={(it: Item, path: Item[]) => { $page = it.id; $last = path.map((x: Item) => x.label).join(" › ") }} />
    </div>
    <div sx={{ flex: "col", gap: 2 }}>
      <Toggle bind:value={$magnify} label="Büyüteç (magnify)" />
      <Toggle bind:value={$bend} label="İplik eğilsin (bend)" />
      <Toggle bind:value={$search} label="Kapsülde arama (search)" />
      <Toggle bind:value={$crumbs} label="Konum yolu (crumbs)" />
      <Toggle bind:value={$close} label="Seçince kapan (closeOnNavigate)" />
      <span sx={{ text: "lg" }}>{`Sayfa: ${threadPath(tree, $page).at(-1)?.label ?? "—"}`}</span>
      <span sx={{ text: "sm", color: "muted" }}>{`Seçilen: ${$last || "henüz yok"}`}</span>
    </div>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ThreadNavLab } from "./ThreadNavLab.tsx"

// ThreadNavLab'in testleri: kaydedince Testler sekmesinde çalışır
test("labels.group iplikteki nav'ın adı; class köke eklenir", () => {
  const s = renderTest(() => <ThreadNavLab />)
  expect(s.find("Lab gezinme")?.tagName).toBe("NAV")
  expect(s.get(".lab-thread")).not.toBe(null)
  expect(s.get('.m-thn-bead[aria-label="Bileşenler"]')?.getAttribute("aria-current")).toBe("location")
})

test("Bir boncuk kapsülü açar; bir sayfa seçilince onNavigate yolu verir, kapsül kapanır", async () => {
  const s = renderTest(() => <ThreadNavLab />)
  await s.click("Bileşenler")
  expect(s.get('.m-thn-bead[aria-label="Bileşenler"]')?.getAttribute("aria-expanded")).toBe("true")
  expect(s.get(".m-thn-panel")).not.toBe(null)
  await s.click("Çubuk")
  expect(s.sees("Seçilen: Bileşenler › Grafikler › Çubuk")).toBe(true)
  expect(s.get(".m-thn-panel")).toBe(null)
})

test("Arama süzer, eşleşen yoksa labels.empty görünür; labels.close kapsülü kapatır", async () => {
  const s = renderTest(() => <ThreadNavLab />)
  await s.click("Görünüm")
  await s.type("Lab'da ara", "zzz")
  await s.wait(() => s.sees("Burada bir şey yok"))
  expect(s.sees("Burada bir şey yok")).toBe(true)
  await s.click("Kapsülü kapat")
  expect(s.get(".m-thn-panel")).toBe(null)
})

test("href verilen kategori bir bağlantı; kategorisiz bölüm kendisi gider", async () => {
  const s = renderTest(() => <ThreadNavLab />)
  await s.click("Hakkında")
  expect(s.find("Sürüm notları")?.closest("a")?.getAttribute("href")).toBe("https://marchjs.com")
  await s.click("Profil")
  expect(s.sees("Sayfa: Profil")).toBe(true)
})
